CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY AUTOINCREMENT, booking_reference VARCHAR(50) UNIQUE NOT NULL, user_id INTEGER, property_id VARCHAR(50) NOT NULL, guest_name VARCHAR(255) NOT NULL, guest_email VARCHAR(255) NOT NULL, guest_phone VARCHAR(50) NOT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, total_nights INTEGER NOT NULL, adults INTEGER DEFAULT 1, children INTEGER DEFAULT 0, units_cost INTEGER DEFAULT 0, total_amount_usd DECIMAL(10,2) NOT NULL, status VARCHAR(50) DEFAULT 'pending', payment_method VARCHAR(50) DEFAULT 'wire', settled_from_units INTEGER DEFAULT 0, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
